//! The `gonq` Tauri plugin: `init()` installs the managed state the commands need (SSH pool and remote fs with the `ssh` feature, GitHub client)
//! and the one command list (`commands`, which the desktop crate also reads to generate bindings.ts). Commands are
//! invoked as `plugin:gonq|<name>` and allowed by the `gonq:default` permission set generated by build.rs.
//! `DataPaths` stays with the app, which resolves it in its own setup (tests manage their own).
use crate::github;
#[cfg(feature = "ssh")]
use crate::ssh;
use tauri::plugin::{Builder, TauriPlugin};
use tauri::{Manager, Runtime};
use tauri_specta::{collect_commands, Commands};

/// The plugin's name; the permission identifiers are `gonq:<permission>` and the command names `plugin:gonq|<command>`.
pub const NAME: &str = "gonq";

/// Every plugin command, in the order of `command_names::COMMANDS`. Add a new command here and there, nowhere else.
pub fn commands<R: Runtime>() -> Commands<R> {
    #[cfg(feature = "ssh")]
    return collect_commands![
        crate::commands::allow_document_folder::<tauri::Wry>,
        crate::commands::list_directory::<tauri::Wry>,
        crate::commands::path_exists,
        crate::commands::recent_documents_add,
        crate::commands::recent_documents_list,
        crate::commands::recent_documents_remove,
        crate::commands::allow_recent_document::<tauri::Wry>,
        crate::commands::get_author_name,
        crate::commands::set_author_name,
        crate::commands::get_theme,
        crate::commands::set_theme,
        crate::commands::get_pane_widths,
        crate::commands::set_pane_width,
        github::github_start,
        github::github_poll,
        github::github_status,
        github::github_sign_out,
        github::github_list_repos,
        github::github_list_branches,
        github::github_list_folder,
        github::github_read_file,
        github::github_commit_file,
        github::github_open_pulls_for_branches,
        github::github_branch_exists,
        github::github_create_branch,
        github::github_branches_exist,
        github::github_compare,
        github::github_create_pull,
        ssh::ssh_list_hosts,
        ssh::ssh_connect,
        ssh::ssh_disconnect,
        ssh::remote_list_folders,
        ssh::remote_open_root,
        ssh::remote_list_directory,
        ssh::remote_read,
        ssh::remote_write,
        ssh::remote_exists,
    ];
    #[cfg(not(feature = "ssh"))]
    return collect_commands![
        crate::commands::allow_document_folder::<tauri::Wry>,
        crate::commands::list_directory::<tauri::Wry>,
        crate::commands::path_exists,
        crate::commands::recent_documents_add,
        crate::commands::recent_documents_list,
        crate::commands::recent_documents_remove,
        crate::commands::allow_recent_document::<tauri::Wry>,
        crate::commands::get_author_name,
        crate::commands::set_author_name,
        crate::commands::get_theme,
        crate::commands::set_theme,
        crate::commands::get_pane_widths,
        crate::commands::set_pane_width,
        github::github_start,
        github::github_poll,
        github::github_status,
        github::github_sign_out,
        github::github_list_repos,
        github::github_list_branches,
        github::github_list_folder,
        github::github_read_file,
        github::github_commit_file,
        github::github_open_pulls_for_branches,
        github::github_branch_exists,
        github::github_create_branch,
        github::github_branches_exist,
        github::github_compare,
        github::github_create_pull,
    ];
}

/// The plugin an app installs with `.plugin(gonq_core::init())`.
pub fn init<R: Runtime>() -> TauriPlugin<R> {
    let handler = commands::<R>().0;
    Builder::new(NAME)
        .setup(|app, _api| {
            #[cfg(feature = "ssh")]
            app.manage(ssh::new_pool());
            app.manage(github::Github::production());
            #[cfg(feature = "ssh")]
            app.manage(ssh::fs::Remote::default());
            Ok(())
        })
        .invoke_handler(move |invoke| handler(invoke))
        .build()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::command_names::COMMANDS;
    use std::collections::BTreeSet;
    use std::path::Path;

    fn manifest_file(rel: &str) -> String {
        std::fs::read_to_string(Path::new(env!("CARGO_MANIFEST_DIR")).join(rel)).unwrap_or_else(|e| panic!("{rel}: {e}"))
    }

    /// The names in `command_names::COMMANDS` are exactly the commands `commands()` registers.
    #[test]
    fn command_names_match_the_registered_commands() {
        let mut types = specta::Types::default();
        let registered: Vec<String> = (commands::<tauri::Wry>().1)(&mut types).functions.iter().map(|f| f.name().to_string()).collect();
        assert_eq!(registered, COMMANDS, "command_names::COMMANDS and plugin::commands must list the same commands in the same order");
    }

    /// A command missing from the default permission set is refused at runtime only ("not allowed by ACL"), so this is the guard:
    /// every command is granted by `gonq:default`, nothing else is, and each granted permission was generated.
    #[test]
    fn default_permission_set_allows_every_command() {
        let default: serde_json::Value = serde_json::from_str(&manifest_file("permissions/default.json")).unwrap();
        let granted: BTreeSet<String> =
            default["default"]["permissions"].as_array().expect("default.permissions").iter().map(|p| p.as_str().unwrap().to_string()).collect();
        // Permissions exist for the SSH commands in every build (build.rs), so default.json names them even without the feature.
        let all: Vec<&str> = crate::command_names::BASE.iter().chain(crate::command_names::SSH).copied().collect();
        let expected: BTreeSet<String> = all.iter().map(|c| format!("allow-{}", c.replace('_', "-"))).collect();
        assert_eq!(granted, expected, "permissions/default.json must allow every command and nothing else");
        for command in &all {
            let file = format!("permissions/autogenerated/commands/{command}.toml");
            let toml = manifest_file(&file);
            assert!(toml.contains(&format!("allow-{}", command.replace('_', "-"))), "{file} must define the allow permission");
        }
    }
}
